import { Routes, Route } from 'react-router-dom';
import { CssBaseline } from '@mui/material'; // Remove ThemeProvider import
import { ThemeModeProvider } from './context/ThemeContext'; // Import ThemeModeProvider
import { AuthProvider } from './context/AuthContext';
import { ProjectCreationProvider } from './context/ProjectCreationContext'; // Import the provider
import MainLayout from './layouts/MainLayout';
import ProtectedRoute from './components/ProtectedRoute';

// Pages
import LoginPage from './components/auth/LoginPage';
import RegisterPage from './components/auth/RegisterPage';
import ProjectListPage from './pages/projectListPage';
import ProjectDetailPage from './pages/projectDetailPage';
import TaskDetailPage from './pages/taskDetailPage';
import DashboardPage from './pages/dashboardPage';
import ProjectBoardPage from './pages/ProjectBoardPage';
import AdminPage from './pages/AdminPage'; // Import AdminPage

function App() {
  return (
    <ThemeModeProvider> {/* Wrap with ThemeModeProvider */}
      <CssBaseline />
      <AuthProvider>
        <ProjectCreationProvider> {/* Wrap with ProjectCreationProvider */}
          <Routes>
            {/* Public Routes */}
            <Route path="/login" element={<LoginPage />} />
            <Route path="/register" element={<RegisterPage />} />

            {/* Protected Routes */}
            <Route element={<ProtectedRoute />}>
              <Route element={<MainLayout />}>
                <Route path="/" element={<ProjectListPage />} /> {/* Redirect/Home */}
                <Route path="/dashboard" element={<DashboardPage />} />
                <Route path="/projects" element={<ProjectListPage />} />
                <Route path="/projects/:projectId" element={<ProjectDetailPage />} />
                <Route path="/tasks" element={<ProjectBoardPage />} />
                <Route path="/tasks/:taskId" element={<TaskDetailPage />} />
                <Route path="/admin" element={<AdminPage />} /> {/* Admin Route */}
              </Route>
            </Route>
          </Routes>
        </ProjectCreationProvider>
      </AuthProvider>
    </ThemeModeProvider>
  );
}

export default App;

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

import crud, schemas, models
from database import get_db
from .auth import get_current_active_user
from utils.permissions import check_project_access

router = APIRouter()

# Task Endpoints
@router.post("/projects/{project_id}/tasks/", response_model=schemas.Task, status_code=status.HTTP_201_CREATED,
            summary="Create a new task for a specific project",
            description="Allows a user with edit access to a project to create a new task within it. Optionally includes assignees, tags, and topics.")
def create_task_for_project(
    project_id: int,
    task: schemas.TaskCreate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    check_project_access(db, project_id, current_user.id, min_role="edit")
    task.project_id = project_id
    # Ensure the owner_id and promoter_id (if provided) are valid users
    if not crud.get_user(db, user_id=task.owner_id):
        raise HTTPException(status_code=400, detail="Task owner not found")
    if task.promoter_ids:
        for p_id in task.promoter_ids:
            if not crud.get_user(db, user_id=p_id):
                raise HTTPException(status_code=400, detail=f"Task promoter with ID {p_id} not found")
    return crud.create_task(db=db, task=task)

@router.get("/projects/{project_id}/tasks/", response_model=list[schemas.Task],
            summary="Retrieve all tasks for a specific project",
            description="Returns a list of tasks within a given project if the authenticated user has view access.")
def read_tasks_for_project(
    project_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
    skip: int = 0,
    limit: int = 100,
):
    check_project_access(db, project_id, current_user.id, min_role="view")
    tasks = crud.get_tasks(db, project_id=project_id, skip=skip, limit=limit)
    return tasks

@router.get("/tasks/{task_id}", response_model=schemas.Task,
            summary="Retrieve a specific task by ID",
            description="Returns a single task if the authenticated user has view access to its parent project.")
def read_task(
    task_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_task = crud.get_task(db, task_id=task_id)
    if db_task is None:
        raise HTTPException(status_code=404, detail="Task not found")
    check_project_access(db, db_task.project_id, current_user.id, min_role="view")
    return db_task

@router.put("/tasks/{task_id}", response_model=schemas.Task,
            summary="Update an existing task",
            description="Allows a user with edit access to the parent project to update a task's details, including assignees, tags, and topics.")
def update_task(
    task_id: int,
    task: schemas.TaskUpdate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_task = crud.get_task(db, task_id=task_id)
    if db_task is None:
        raise HTTPException(status_code=404, detail="Task not found")
    check_project_access(db, db_task.project_id, current_user.id, min_role="edit")
    return crud.update_task(db=db, task_id=task_id, task=task)

@router.delete("/tasks/{task_id}", status_code=status.HTTP_204_NO_CONTENT,
            summary="Delete a task",
            description="Allows a user with edit access to the parent project to delete a specific task.")
def delete_task(
    task_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_task = crud.get_task(db, task_id=task_id)
    if db_task is None:
        raise HTTPException(status_code=404, detail="Task not found")
    check_project_access(db, db_task.project_id, current_user.id, min_role="edit")
    crud.delete_task(db=db, task_id=task_id)
    return

# Subtask Endpoints
@router.post("/tasks/{task_id}/subtasks/", response_model=schemas.Subtask, status_code=status.HTTP_201_CREATED,
            summary="Create a new subtask for a specific task or nested under another subtask",
            description="Allows a user with edit access to the parent task's project to create a new subtask. The subtask can be a direct child of the task or nested under an existing subtask using `parent_subtask_id`.")
def create_subtask_for_task(
    task_id: int,
    subtask: schemas.SubtaskCreate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
    parent_subtask_id: int | None = None, # Optional parameter for nested subtasks
):
    # Determine the project ID for access check
    project_id = None
    if parent_subtask_id:
        db_parent_subtask = crud.get_subtask(db, subtask_id=parent_subtask_id)
        if db_parent_subtask is None:
            raise HTTPException(status_code=404, detail="Parent subtask not found")
        # Ensure parent_task_id is derived from parent subtask's parent task
        if db_parent_subtask.parent_task_id is None:
            raise HTTPException(status_code=400, detail="Parent subtask must be associated with a task.")
        project_id = crud.get_task(db, db_parent_subtask.parent_task_id).project_id

    else:
        db_task = crud.get_task(db, task_id=task_id)
        if db_task is None:
            raise HTTPException(status_code=404, detail="Parent task not found")
        project_id = db_task.project_id

    # Check project access
    check_project_access(db, project_id, current_user.id, min_role="edit")

    # Set parent IDs
    if parent_subtask_id:
        subtask.parent_subtask_id = parent_subtask_id
        subtask.parent_task_id = crud.get_subtask(db, parent_subtask_id).parent_task_id # Inherit parent task from parent subtask
    else:
        subtask.parent_task_id = task_id
        subtask.parent_subtask_id = None # Explicitly set to None if creating under task

    if not crud.get_user(db, user_id=subtask.owner_id):
        raise HTTPException(status_code=400, detail="Subtask owner not found")

    return crud.create_subtask(db=db, subtask=subtask)

@router.get("/tasks/{task_id}/subtasks/", response_model=list[schemas.Subtask],
            summary="Retrieve subtasks for a given task or nested subtasks",
            description="Returns a list of subtasks. If `parent_subtask_id` is provided, returns sub-subtasks. Otherwise, returns top-level subtasks for the specified task.")
def read_subtasks_for_task(
    task_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
    parent_subtask_id: int | None = None, # New parameter for nested subtasks
    skip: int = 0,
    limit: int = 100,
):
    # Check access to the parent task's project
    db_task = crud.get_task(db, task_id=task_id)
    if db_task is None:
        raise HTTPException(status_code=404, detail="Parent task not found")
    check_project_access(db, db_task.project_id, current_user.id, min_role="view")

    # If parent_subtask_id is provided, ensure it belongs to the current task's hierarchy
    if parent_subtask_id:
        db_parent_subtask = crud.get_subtask(db, subtask_id=parent_subtask_id)
        if db_parent_subtask is None or (db_parent_subtask.parent_task_id != task_id and db_parent_subtask.parent_task_id != db_task.id): # Check immediate parent or higher up if needed
            raise HTTPException(status_code=404, detail="Parent subtask not found under this task.")
        return crud.get_subtasks(db, parent_subtask_id=parent_subtask_id, skip=skip, limit=limit)
    else:
        # Fetch top-level subtasks for the task
        return crud.get_subtasks(db, parent_task_id=task_id, skip=skip, limit=limit)

@router.get("/subtasks/{subtask_id}", response_model=schemas.Subtask,
            summary="Retrieve a specific subtask by ID",
            description="Returns a single subtask if the authenticated user has view access to its parent project.")
def read_subtask(
    subtask_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_subtask = crud.get_subtask(db, subtask_id=subtask_id)
    if db_subtask is None:
        raise HTTPException(status_code=404, detail="Subtask not found")
    # Determine the project ID based on parent_task_id or parent_subtask_id
    project_id = None
    if db_subtask.parent_task_id:
        db_task = crud.get_task(db, task_id=db_subtask.parent_task_id)
        if db_task: project_id = db_task.project_id
    elif db_subtask.parent_subtask_id:
        # Find the top-most parent task's project for access check
        current_sub = db_subtask
        while current_sub and current_sub.parent_subtask_id:
            current_sub = crud.get_subtask(db, subtask_id=current_sub.parent_subtask_id)
        if current_sub and current_sub.parent_task_id:
            db_task = crud.get_task(db, task_id=current_sub.parent_task_id)
            if db_task: project_id = db_task.project_id

    if project_id is None:
        raise HTTPException(status_code=400, detail="Could not determine parent project for access check.")

    check_project_access(db, project_id, current_user.id, min_role="view")
    return db_subtask

@router.put("/subtasks/{subtask_id}", response_model=schemas.Subtask,
            summary="Update an existing subtask",
            description="Allows a user with edit access to the parent project to update a subtask's details, including its parentage (task or subtask).")
def update_subtask(
    subtask_id: int,
    subtask: schemas.SubtaskUpdate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_subtask = crud.get_subtask(db, subtask_id=subtask_id)
    if db_subtask is None:
        raise HTTPException(status_code=404, detail="Subtask not found")

    # Determine the project ID based on parent_task_id or parent_subtask_id
    project_id = None
    if db_subtask.parent_task_id:
        db_task = crud.get_task(db, task_id=db_subtask.parent_task_id)
        if db_task: project_id = db_task.project_id
    elif db_subtask.parent_subtask_id:
        current_sub = db_subtask
        while current_sub and current_sub.parent_subtask_id:
            current_sub = crud.get_subtask(db, subtask_id=current_sub.parent_subtask_id)
        if current_sub and current_sub.parent_task_id:
            db_task = crud.get_task(db, task_id=current_sub.parent_task_id)
            if db_task: project_id = db_task.project_id

    if project_id is None:
        raise HTTPException(status_code=400, detail="Could not determine parent project for access check.")

    check_project_access(db, project_id, current_user.id, min_role="edit")
    return crud.update_subtask(db=db, subtask_id=subtask_id, subtask=subtask)

@router.delete("/subtasks/{subtask_id}", status_code=status.HTTP_204_NO_CONTENT,
            summary="Delete a subtask",
            description="Allows a user with edit access to the parent project to delete a specific subtask.")
def delete_subtask(
    subtask_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_subtask = crud.get_subtask(db, subtask_id=subtask_id)
    if db_subtask is None:
        raise HTTPException(status_code=404, detail="Subtask not found")

    # Determine the project ID based on parent_task_id or parent_subtask_id
    project_id = None
    if db_subtask.parent_task_id:
        db_task = crud.get_task(db, task_id=db_subtask.parent_task_id)
        if db_task: project_id = db_task.project_id
    elif db_subtask.parent_subtask_id:
        current_sub = db_subtask
        while current_sub and current_sub.parent_subtask_id:
            current_sub = crud.get_subtask(db, subtask_id=current_sub.parent_subtask_id)
        if current_sub and current_sub.parent_task_id:
            db_task = crud.get_task(db, task_id=current_sub.parent_task_id)
            if db_task: project_id = db_task.project_id

    if project_id is None:
        raise HTTPException(status_code=400, detail="Could not determine parent project for access check.")

    check_project_access(db, project_id, current_user.id, min_role="edit")
    crud.delete_subtask(db=db, subtask_id=subtask_id)
    return

