import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { ProjectsService } from '@/client';
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Plus, MoreVertical, Calendar, Users } from 'lucide-react';
import { Link } from 'react-router-dom';

export default function ProjectListPage() {
  const { data: projects, isLoading } = useQuery({
    queryKey: ['projects'],
    queryFn: () => ProjectsService.readProjectsProjectsGet(),
  });

  if (isLoading) {
    return (
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map((i) => (
          <div key={i} className="h-48 bg-gray-200 rounded-lg dark:bg-gray-800" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Projects</h1>
          <p className="text-muted-foreground">Manage and track all your active projects.</p>
        </div>
        <Button>
          <Plus className="w-4 h-4 mr-2" />
          New Project
        </Button>
      </div>

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {projects?.map((project) => (
          <Card key={project.id} className="group hover:border-primary/50 transition-colors">
            <CardHeader className="flex flex-row items-start justify-between pb-2">
              <div className="space-y-1">
                <Link to={`/projects/${project.id}`} className="hover:underline">
                  <CardTitle className="text-lg font-bold">{project.name}</CardTitle>
                </Link>
                <p className="text-xs text-muted-foreground line-clamp-1">{project.description}</p>
              </div>
              <Button variant="ghost" size="icon" className="opacity-0 group-hover:opacity-100">
                <MoreVertical className="w-4 h-4" />
              </Button>
            </CardHeader>
            <CardContent>
              <div className="flex items-center mt-2 text-xs text-muted-foreground space-x-4">
                <div className="flex items-center">
                  <Calendar className="w-3 h-3 mr-1" />
                  {new Date(project.end_date).toLocaleDateString()}
                </div>
                <div className="flex items-center">
                  <Users className="w-3 h-3 mr-1" />
                  Owner: {project.owner_id}
                </div>
              </div>
            </CardContent>
            <CardFooter className="pt-0">
              <div className="w-full">
                <div className="flex items-center justify-between mb-1 text-xs">
                  <span>Progress</span>
                  <span>{project.progress}%</span>
                </div>
                <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden dark:bg-gray-800">
                  <div 
                    className="h-full bg-primary transition-all duration-500" 
                    style={{ width: `${project.progress}%` }}
                  />
                </div>
              </div>
            </CardFooter>
          </Card>
        ))}
        {(!projects || projects.length === 0) && (
          <div className="col-span-full py-12 text-center border-2 border-dashed rounded-lg">
            <p className="text-muted-foreground">No projects yet. Click "New Project" to get started.</p>
          </div>
        )}
      </div>
    </div>
  );
}

