import React from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Card, CardContent } from '@/components/ui/card';
import { Task } from '@/client';
import { Clock, MessageSquare, Paperclip } from 'lucide-react';

interface KanbanTaskProps {
  task: Task & { projectName?: string };
}

export function KanbanTask({ task }: KanbanTaskProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Translate.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <Card 
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="cursor-grab active:cursor-grabbing hover:border-primary/50 transition-colors"
    >
      <CardContent className="p-4 space-y-3">
        <div className="flex justify-between items-start">
            <span className="text-[10px] font-bold text-primary uppercase bg-primary/10 px-2 py-0.5 rounded">
                {task.projectName}
            </span>
        </div>
        <h4 className="text-sm font-semibold leading-tight">{task.title}</h4>

        <div className="flex items-center justify-between text-gray-500">
            <div className="flex items-center space-x-3">
                <div className="flex items-center text-[10px]">
                    <Clock className="w-3 h-3 mr-1" />
                    {new Date(task.end_date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                </div>
                {task.progress > 0 && (
                    <div className="text-[10px] font-medium text-green-600">
                        {task.progress}%
                    </div>
                )}
            </div>

            <div className="flex items-center space-x-2 opacity-50">
                <MessageSquare className="w-3 h-3" />
                <Paperclip className="w-3 h-3" />
            </div>
        </div>
      </CardContent>
    </Card>
  );
}

