import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { ProjectsService, TasksService, Task, Subtask } from '@/client';
import { Button } from '@/components/ui/button';
import { UICard, UICardContent } from '@/components/ui/card'; // Wait, I named them Card earlier.
import { Card, CardContent } from '@/components/ui/card';
import { ChevronRight, ChevronDown, CheckCircle2, Circle, Clock } from 'lucide-react';
import { cn } from '@/lib/utils';

export default function ProjectDetailPage() {
  const { projectId } = useParams<{ projectId: string }>();
  const [view, setView] = useState<'list' | 'board'>('list');

  const { data: project, isLoading } = useQuery({
    queryKey: ['project', projectId],
    queryFn: () => ProjectsService.readProjectProjectsProjectIdGet(Number(projectId)),
  });

  if (isLoading) return <div>Loading project...</div>;
  if (!project) return <div>Project not found</div>;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">{project.name}</h1>
          <p className="text-muted-foreground">{project.description}</p>
        </div>
        <div className="flex bg-gray-100 dark:bg-gray-800 p-1 rounded-lg">
          <Button 
            variant={view === 'list' ? 'default' : 'ghost'} 
            size="sm" 
            onClick={() => setView('list')}
          >
            List
          </Button>
          <Button 
            variant={view === 'board' ? 'default' : 'ghost'} 
            size="sm" 
            onClick={() => setView('board')}
          >
            Board
          </Button>
        </div>
      </div>

      {view === 'list' ? (
        <div className="space-y-4">
           {project.tasks?.map(task => (
             <TaskListItem key={task.id} task={task} />
           ))}
        </div>
      ) : (
        <div className="text-center py-20 text-muted-foreground border-2 border-dashed rounded-lg">
            Board view for specific project coming soon (integrated from TaskBoard)
        </div>
      )}
    </div>
  );
}

function TaskListItem({ task }: { task: Task }) {
    const [isExpanded, setIsExpanded] = useState(true);
    const hasSubtasks = task.subtasks && task.subtasks.length > 0;

    return (
        <div className="border border-gray-200 dark:border-gray-800 rounded-lg overflow-hidden bg-white dark:bg-gray-950">
            <div 
                className="flex items-center p-4 hover:bg-gray-50 dark:hover:bg-gray-900 transition-colors cursor-pointer"
                onClick={() => setIsExpanded(!isExpanded)}
            >
                <div className="mr-3">
                    {hasSubtasks ? (
                        isExpanded ? <ChevronDown className="w-4 h-4 text-gray-400" /> : <ChevronRight className="w-4 h-4 text-gray-400" />
                    ) : (
                        <div className="w-4 h-4" />
                    )}
                </div>
                <div className="flex-1">
                    <div className="flex items-center justify-between">
                        <span className="font-medium">{task.title}</span>
                        <div className="flex items-center space-x-4 text-xs text-muted-foreground">
                            <span className={cn(
                                "px-2 py-0.5 rounded-full text-[10px] font-bold uppercase",
                                task.status === 'Completed' ? "bg-green-100 text-green-700" : "bg-blue-100 text-blue-700"
                            )}>
                                {task.status}
                            </span>
                            <span className="flex items-center">
                                <Clock className="w-3 h-3 mr-1" />
                                {new Date(task.end_date).toLocaleDateString()}
                            </span>
                            <span className="font-bold text-primary">{task.progress}%</span>
                        </div>
                    </div>
                </div>
            </div>
            {isExpanded && hasSubtasks && (
                <div className="bg-gray-50/50 dark:bg-gray-900/50 border-t dark:border-gray-800 p-2 pl-8 space-y-2">
                    {task.subtasks?.map(sub => (
                        <SubtaskItem key={sub.id} subtask={sub} level={1} />
                    ))}
                </div>
            )}
        </div>
    );
}

function SubtaskItem({ subtask, level }: { subtask: Subtask, level: number }) {
    const [isExpanded, setIsExpanded] = useState(false);
    const hasNested = subtask.nested_subtasks && subtask.nested_subtasks.length > 0;

    return (
        <div className="space-y-1">
            <div className="flex items-center py-2 text-sm group">
                <div className="mr-2" onClick={() => setIsExpanded(!isExpanded)}>
                    {hasNested ? (
                        isExpanded ? <ChevronDown className="w-3 h-3 text-gray-400" /> : <ChevronRight className="w-3 h-3 text-gray-400" />
                    ) : (
                        <Circle className="w-2 h-2 text-gray-300 ml-0.5" />
                    )}
                </div>
                <div className="flex-1 flex items-center justify-between">
                    <span className={cn(
                        "transition-colors",
                        subtask.status === 'Completed' ? "text-gray-400 line-through" : "text-gray-700 dark:text-gray-300"
                    )}>
                        {subtask.name}
                    </span>
                    <div className="flex items-center space-x-3 opacity-0 group-hover:opacity-100 transition-opacity">
                        <span className="text-[10px] text-muted-foreground">{subtask.progress}%</span>
                    </div>
                </div>
            </div>
            {isExpanded && hasNested && (
                <div className="pl-4 border-l dark:border-gray-800 ml-1.5 space-y-1">
                    {subtask.nested_subtasks?.map(nested => (
                        <SubtaskItem key={nested.id} subtask={nested} level={level + 1} />
                    ))}
                </div>
            )}
        </div>
    );
}

