import * as React from "react"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

interface SheetProps {
  isOpen: boolean
  onClose: () => void
  title: string
  description?: string
  children: React.ReactNode
}

export function Sheet({ isOpen, onClose, title, description, children }: SheetProps) {
  // Use a state to handle the animation class
  const [shouldRender, setShouldRender] = React.useState(isOpen)

  React.useEffect(() => {
    if (isOpen) setShouldRender(true)
  }, [isOpen])

  const onAnimationEnd = () => {
    if (!isOpen) setShouldRender(false)
  }

  if (!shouldRender) return null

  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      {/* Backdrop */}
      <div 
        className={cn(
          "fixed inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-300",
          isOpen ? "opacity-100" : "opacity-0"
        )}
        onClick={onClose}
      />

      {/* Content */}
      <div 
        onAnimationEnd={onAnimationEnd}
        className={cn(
          "relative w-full max-w-md h-full bg-white dark:bg-gray-950 shadow-2xl transform transition-transform duration-300 ease-in-out flex flex-col",
          isOpen ? "translate-x-0" : "translate-x-full"
