import { KanbanColumn } from '@/components/kanban/KanbanColumn';
import { KanbanTask } from '@/components/kanban/KanbanTask';
import { TaskDetailSheet } from '@/components/tasks/TaskDetailSheet';

const STATUSES = ['Not Started', 'In Progress', 'Completed', 'On Hold'] as const;

export default function TaskBoardPage() {
  const queryClient = useQueryClient();
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isSheetOpen, setIsSheetOpen] = useState(false);

  const { data: projects, isLoading } = useQuery({
    queryKey: ['projects-summary'],
    queryFn: () => ProjectsService.getSummaryGanttDataProjectsSummaryGanttGet(),
  });

  const [activeTask, setActiveTask] = useState<(Task & { projectName?: string }) | null>(null);

  const allTasks = useMemo(() => {
    return projects?.flatMap(p => p.tasks?.map(t => ({...t, projectName: p.name})) || []) || [];
  }, [projects]);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const mutation = useMutation({
    mutationFn: ({ taskId, status }: { taskId: number, status: string }) => 
      TasksService.updateTaskTasksTaskIdPut(taskId, { status } as any),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['projects-summary'] });
    }
  });

  const handleTaskClick = (task: Task) => {
    setSelectedTask(task);
    setIsSheetOpen(true);
  };

  function handleDragStart(event: DragStartEvent) {
    const { active } = event;
    const task = allTasks.find(t => t.id === active.id);
    if (task) setActiveTask(task);
  }

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;

    if (!over) return;

    const taskId = active.id as number;
    const newStatus = over.id as string;

    const task = allTasks.find(t => t.id === taskId);

    if (task && task.status !== newStatus && STATUSES.includes(newStatus as any)) {
      mutation.mutate({ taskId, status: newStatus });
    }

    setActiveTask(null);
  }

  if (isLoading) return <div>Loading board...</div>;

  return (
    <div className="h-full flex flex-col space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Task Board</h1>
        <p className="text-muted-foreground">Drag and drop tasks to update their status.</p>
      </div>

      <DndContext 
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="flex-1 flex space-x-4 overflow-x-auto pb-4">
          {STATUSES.map(status => (
            <SortableContext 
                key={status} 
                items={allTasks.filter(t => t.status === status).map(t => t.id)}
                strategy={verticalListSortingStrategy}
            >
                <KanbanColumn 
                    title={status} 
                    tasks={allTasks.filter(t => t.status === status)}
                    onTaskClick={handleTaskClick}
                />
            </SortableContext>
          ))}
        </div>

        <DragOverlay dropAnimation={{
            sideEffects: defaultDropAnimationSideEffects({
                styles: {
                    active: {
                        opacity: '0.5',
                    },
                },
            }),
        }}>
          {activeTask ? (
            <KanbanTask task={activeTask} />
          ) : null}
        </DragOverlay>
      </DndContext>

      <TaskDetailSheet 
        task={selectedTask}
        isOpen={isSheetOpen}
        onClose={() => setIsSheetOpen(false)}
      />
    </div>
  );
}

