import React, { useState, useMemo } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { ProjectsService, TasksService, Task } from '@/client';
import { 
  DndContext, 
  DragOverlay, 
  closestCorners, 
  KeyboardSensor, 
  PointerSensor, 
  useSensor, 
  useSensors,
  DragStartEvent,
  DragOverEvent,
  DragEndEvent,
  defaultDropAnimationSideEffects
} from '@dnd-kit/core';
import { 
  arrayMove, 
  SortableContext, 
  sortableKeyboardCoordinates, 
  verticalListSortingStrategy 
} from '@dnd-kit/sortable';
import { KanbanColumn } from '@/components/kanban/KanbanColumn';
import { KanbanTask } from '@/components/kanban/KanbanTask';
import { TaskDetailSheet } from '@/components/tasks/TaskDetailSheet';

const STATUSES = ['Not Started', 'In Progress', 'Completed', 'On Hold'] as const;

export default function TaskBoardPage() {
  const queryClient = useQueryClient();
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isSheetOpen, setIsSheetOpen] = useState(false);

  const { data: projects, isLoading } = useQuery({
    queryKey: ['projects-summary'],
    queryFn: () => ProjectsService.getSummaryGanttDataProjectsSummaryGanttGet(),
  });

  const [activeTask, setActiveTask] = useState<(Task & { projectName?: string }) | null>(null);

  const allTasks = useMemo(() => {
    return projects?.flatMap(p => p.tasks?.map(t => ({...t, projectName: p.name})) || []) || [];
  }, [projects]);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const mutation = useMutation({
    mutationFn: ({ taskId, status }: { taskId: number, status: string }) => 
      TasksService.updateTaskTasksTaskIdPut(taskId, { status } as any),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['projects-summary'] });
    }
  });

  const handleTaskClick = (task: Task) => {
    setSelectedTask(task);
    setIsSheetOpen(true);
  };

  function handleDragStart(event: DragStartEvent) {
    const { active } = event;
    const task = allTasks.find(t => t.id === active.id);
    if (task) setActiveTask(task);
  }

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;

    if (!over) return;

    const taskId = active.id as number;
    const newStatus = over.id as string;

    const task = allTasks.find(t => t.id === taskId);

    if (task && task.status !== newStatus && STATUSES.includes(newStatus as any)) {
      mutation.mutate({ taskId, status: newStatus });
    }

    setActiveTask(null);
  }

  if (isLoading) return <div>Loading board...</div>;

  return (
    <div className="h-full flex flex-col space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Task Board</h1>
        <p className="text-muted-foreground">Drag and drop tasks to update their status.</p>
      </div>

      <DndContext 
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="flex-1 flex space-x-4 overflow-x-auto pb-4">
          {STATUSES.map(status => (
            <SortableContext 
                key={status} 
                items={allTasks.filter(t => t.status === status).map(t => t.id)}
                strategy={verticalListSortingStrategy}
            >
                <KanbanColumn 
                    title={status} 
                    tasks={allTasks.filter(t => t.status === status)}
                    onTaskClick={handleTaskClick}
                />
            </SortableContext>
          ))}
        </div>

        <DragOverlay dropAnimation={{
            sideEffects: defaultDropAnimationSideEffects({
                styles: {
                    active: {
                        opacity: '0.5',
                    },
                },
            }),
        }}>
          {activeTask ? (
            <KanbanTask task={activeTask} />
          ) : null}
        </DragOverlay>
      </DndContext>

      <TaskDetailSheet 
        task={selectedTask}
        isOpen={isSheetOpen}
        onClose={() => setIsSheetOpen(false)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ProjectsService } from '@/client';
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Plus, MoreVertical, Calendar, Users } from 'lucide-react';
import { Link } from 'react-router-dom';
import { CreateProjectModal } from '@/components/projects/CreateProjectModal';

export default function ProjectListPage() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { data: projects, isLoading } = useQuery({
    queryKey: ['projects'],
    queryFn: () => ProjectsService.readProjectsProjectsGet(),
  });

  if (isLoading) {
    return (
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map((i) => (
          <div key={i} className="h-48 bg-gray-200 rounded-lg dark:bg-gray-800" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Projects</h1>
          <p className="text-muted-foreground">Manage and track all your active projects.</p>
        </div>
        <Button onClick={() => setIsModalOpen(true)}>
          <Plus className="w-4 h-4 mr-2" />
          New Project
        </Button>
      </div>

      <CreateProjectModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
      />

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {projects?.map((project) => (
          <Card key={project.id} className="group hover:border-primary/50 transition-colors">
            <CardHeader className="flex flex-row items-start justify-between pb-2">
              <div className="space-y-1">
                <Link to={`/projects/${project.id}`} className="hover:underline">
                  <CardTitle className="text-lg font-bold">{project.name}</CardTitle>
                </Link>
                <p className="text-xs text-muted-foreground line-clamp-1">{project.description}</p>
              </div>
              <Button variant="ghost" size="icon" className="opacity-0 group-hover:opacity-100">
                <MoreVertical className="w-4 h-4" />
              </Button>
            </CardHeader>
            <CardContent>
              <div className="flex items-center mt-2 text-xs text-muted-foreground space-x-4">
                <div className="flex items-center">
                  <Calendar className="w-3 h-3 mr-1" />
                  {new Date(project.end_date).toLocaleDateString()}
                </div>
                <div className="flex items-center">
                  <Users className="w-3 h-3 mr-1" />
                  Owner: {project.owner_id}
                </div>
              </div>
            </CardContent>
            <CardFooter className="pt-0">
              <div className="w-full">
                <div className="flex items-center justify-between mb-1 text-xs">
                  <span>Progress</span>
                  <span>{project.progress}%</span>
                </div>
                <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden dark:bg-gray-800">
                  <div 
                    className="h-full bg-primary transition-all duration-500" 
                    style={{ width: `${project.progress}%` }}
                  />
                </div>
              </div>
            </CardFooter>
          </Card>
        ))}
        {(!projects || projects.length === 0) && (
          <div className="col-span-full py-12 text-center border-2 border-dashed rounded-lg">
            <p className="text-muted-foreground">No projects yet. Click "New Project" to get started.</p>
          </div>
        )}
      </div>
    </div>
  );
}

