import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { ProjectsService } from '@/client';
import { Card as UICard, CardContent as UICardContent, CardHeader as UICardHeader, CardTitle as UICardTitle } from '@/components/ui/card';
import { LayoutDashboard, FolderKanban, CheckSquare, Clock } from 'lucide-react';

export default function DashboardPage() {
  const { data: projects, isLoading } = useQuery({
    queryKey: ['projects-summary'],
    queryFn: () => ProjectsService.getSummaryGanttDataProjectsSummaryGanttGet(),
  });

  const stats = [
    {
      label: 'Total Projects',
      value: projects?.length || 0,
      icon: FolderKanban,
      color: 'text-blue-600',
      bg: 'bg-blue-100',
    },
    {
      label: 'Active Tasks',
      value: projects?.reduce((acc, p) => acc + (p.tasks?.length || 0), 0) || 0,
      icon: CheckSquare,
      color: 'text-green-600',
      bg: 'bg-green-100',
    },
    {
      label: 'Avg. Progress',
      value: `${Math.round(
        (projects?.reduce((acc, p) => acc + (p.progress || 0), 0) || 0) / (projects?.length || 1)
      )}%`,
      icon: LayoutDashboard,
      color: 'text-purple-600',
      bg: 'bg-purple-100',
    },
  ];

  if (isLoading) {
    return (
      <div className="space-y-6 animate-pulse">
        <div className="grid gap-4 md:grid-cols-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-32 bg-gray-200 rounded-lg dark:bg-gray-800" />
          ))}
        </div>
        <div className="h-64 bg-gray-200 rounded-lg dark:bg-gray-800" />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground">Overview of your current projects and tasks.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-3">
        {stats.map((stat) => (
          <UICard key={stat.label}>
            <UICardHeader className="flex flex-row items-center justify-between pb-2 space-y-0">
              <UICardTitle className="text-sm font-medium">{stat.label}</UICardTitle>
              <div className={`${stat.bg} ${stat.color} p-2 rounded-md`}>
                <stat.icon className="w-4 h-4" />
              </div>
            </UICardHeader>
            <UICardContent>
              <div className="text-2xl font-bold">{stat.value}</div>
            </UICardContent>
          </UICard>
        ))}
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <UICard className="col-span-1">
          <UICardHeader>
            <UICardTitle>Recent Projects</UICardTitle>
          </UICardHeader>
          <UICardContent>
            <div className="space-y-4">
              {projects?.slice(0, 5).map((project) => (
                <div key={project.id} className="flex items-center">
                  <div className="flex-1 space-y-1">
                    <p className="text-sm font-medium leading-none">{project.name}</p>
                    <p className="text-xs text-muted-foreground">
                      Due {new Date(project.end_date).toLocaleDateString()}
                    </p>
                  </div>
                  <div className="text-sm font-medium">{project.progress}%</div>
                </div>
              ))}
              {(!projects || projects.length === 0) && (
                <p className="text-sm text-muted-foreground">No projects found.</p>
              )}
            </div>
          </UICardContent>
        </UICard>

        <UICard className="col-span-1">
          <UICardHeader>
            <UICardTitle>Upcoming Deadlines</UICardTitle>
          </UICardHeader>
          <UICardContent>
             <div className="space-y-4 text-sm text-muted-foreground">
                {/* Simplified task list extracted from projects */}
                {projects?.flatMap(p => p.tasks?.map(t => ({...t, projectName: p.name})) || [])
                    .sort((a, b) => new Date(a.end_date).getTime() - new Date(b.end_date).getTime())
                    .slice(0, 5)
                    .map(task => (
                        <div key={task.id} className="flex items-center justify-between">
                            <div className="flex items-center">
                                <Clock className="w-4 h-4 mr-2 text-orange-500" />
                                <span>{task.title}</span>
                                <span className="ml-2 text-xs opacity-50">({task.projectName})</span>
                            </div>
                            <span>{new Date(task.end_date).toLocaleDateString()}</span>
                        </div>
                    ))
                }
                {(!projects || projects.length === 0) && (
                    <p>No upcoming deadlines.</p>
                )}
             </div>
          </UICardContent>
        </UICard>
      </div>
    </div>
  );
}

import React, { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Sheet } from '@/components/ui/sheet';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { TasksService, Task } from '@/client';
import { useMutation, useQueryClient } from '@tanstack/react-query';

const taskSchema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
  status: z.string(),
  progress: z.number().min(0).max(100),
  start_date: z.string().optional(),
  end_date: z.string().optional(),
});

type TaskFormValues = z.infer<typeof taskSchema>;

interface TaskDetailSheetProps {
  task: Task | null;
  isOpen: boolean;
  onClose: () => void;
}

export function TaskDetailSheet({ task, isOpen, onClose }: TaskDetailSheetProps) {
  const queryClient = useQueryClient();

  const { register, handleSubmit, reset, formState: { errors } } = useForm<TaskFormValues>({
    resolver: zodResolver(taskSchema),
  });

  useEffect(() => {
    if (task) {
      reset({
        title: task.title,
        description: task.description || '',
        status: task.status || 'Not Started',
        progress: task.progress || 0,
        start_date: task.start_date ? new Date(task.start_date).toISOString().split('T')[0] : '',
        end_date: task.end_date ? new Date(task.end_date).toISOString().split('T')[0] : '',
      });
    }
  }, [task, reset]);

  const mutation = useMutation({
    mutationFn: (data: TaskFormValues) => 
      TasksService.updateTaskTasksTaskIdPut(task!.id, data as any),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['projects-summary'] });
      queryClient.invalidateQueries({ queryKey: ['project'] });
      onClose();
    },
  });

  const onSubmit = (data: TaskFormValues) => {
    mutation.mutate(data);
  };

  return (
    <Sheet 
      isOpen={isOpen} 
      onClose={onClose} 
      title="Edit Task" 
      description="Update task details and track progress."
    >
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input id="title" {...register('title')} />
          {errors.title && <p className="text-xs text-red-500">{errors.title.message}</p>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="description">Description</Label>
          <textarea 
            id="description" 
            {...register('description')}
            className="flex min-h-[100px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="status">Status</Label>
            <select 
              id="status" 
              {...register('status')}
              className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <option value="Not Started">Not Started</option>
              <option value="In Progress">In Progress</option>
              <option value="Completed">Completed</option>
              <option value="On Hold">On Hold</option>
            </select>
          </div>
          <div className="space-y-2">
            <Label htmlFor="progress">Progress ({task?.progress}%)</Label>
            <Input id="progress" type="number" {...register('progress', { valueAsNumber: true })} />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="start_date">Start Date</Label>
            <Input id="start_date" type="date" {...register('start_date')} />
          </div>
          <div className="space-y-2">
            <Label htmlFor="end_date">End Date</Label>
            <Input id="end_date" type="date" {...register('end_date')} />
          </div>
        </div>

        <div className="flex justify-end pt-4 space-x-2">
          <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
          <Button type="submit" disabled={mutation.isPending}>
            {mutation.isPending ? 'Saving...' : 'Save Changes'}
          </Button>
        </div>
      </form>
    </Sheet>
  );
}

