import React, { useMemo } from 'react';
import { Task } from '@/client';
import { 
  format, 
  startOfMonth, 
  endOfMonth, 
  eachDayOfInterval, 
  isWithinInterval, 
  differenceInDays,
  addDays,
  startOfDay,
  endOfDay
} from 'date-fns';
import { cn } from '@/lib/utils';

interface ProjectTimelineProps {
  tasks: Task[];
  startDate: string;
  endDate: string;
}

export function ProjectTimeline({ tasks, startDate, endDate }: ProjectTimelineProps) {
  const projectStart = startOfDay(new Date(startDate));
  const projectEnd = endOfDay(new Date(endDate));
  const totalDays = differenceInDays(projectEnd, projectStart) + 1;

  // Generate day headers (simple version)
  const days = useMemo(() => {
    return Array.from({ length: totalDays }).map((_, i) => addDays(projectStart, i));
  }, [projectStart, totalDays]);

  return (
    <div className="border rounded-lg bg-white dark:bg-gray-950 overflow-hidden">
      <div className="overflow-x-auto">
        <div className="min-w-[800px]">
          {/* Header - Months/Days */}
          <div className="flex border-b dark:border-gray-800">
            <div className="w-48 flex-shrink-0 border-r dark:border-gray-800 p-4 font-bold text-sm bg-gray-50 dark:bg-gray-900">
              Task
            </div>
            <div className="flex-1 flex overflow-hidden">
                {/* Simplified timeline header */}
                <div className="flex w-full">
                    {days.map((day, i) => (
                        <div 
                            key={i} 
                            className={cn(
                                "flex-1 min-w-[30px] border-r dark:border-gray-800 text-[10px] text-center py-2 text-gray-400",
                                i % 7 === 0 ? "bg-gray-50 dark:bg-gray-900 font-bold text-gray-600" : ""
                            )}
                        >
                            {format(day, 'd')}
                        </div>
                    ))}
                </div>
            </div>
          </div>

          {/* Rows */}
          <div className="divide-y dark:divide-gray-800">
            {tasks.map((task) => {
              const taskStart = startOfDay(new Date(task.start_date || startDate));
              const taskEnd = endOfDay(new Date(task.end_date || endDate));

              const startOffset = Math.max(0, differenceInDays(taskStart, projectStart));
              const duration = differenceInDays(taskEnd, taskStart) + 1;

              const leftPercent = (startOffset / totalDays) * 100;
              const widthPercent = (duration / totalDays) * 100;

              return (
                <div key={task.id} className="flex group hover:bg-gray-50 dark:hover:bg-gray-900 transition-colors">
                  <div className="w-48 flex-shrink-0 border-r dark:border-gray-800 p-3 text-xs font-medium truncate">
                    {task.title}
                  </div>
                  <div className="flex-1 relative h-12 flex items-center">
                    {/* Grid lines */}
                    <div className="absolute inset-0 flex">
                        {days.map((_, i) => (
                            <div key={i} className="flex-1 border-r dark:border-gray-800 last:border-r-0 opacity-20" />
                        ))}
                    </div>

                    {/* Task Bar */}
                    <div 
                      className="absolute h-6 bg-primary/20 border border-primary/30 rounded-md flex items-center px-2 group-hover:bg-primary/30 transition-all shadow-sm"
                      style={{ 
                        left: `${leftPercent}%`, 
                        width: `${widthPercent}%`,
                        minWidth: '4px'
                      }}
                    >
                        <div className="absolute inset-y-0 left-0 bg-primary opacity-40 rounded-l-md" style={{ width: `${task.progress}%` }} />
                        <span className="relative z-10 text-[10px] font-bold text-primary-foreground mix-blend-difference truncate">
                            {task.progress}%
                        </span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

